/**
 * Server-only: draw a multi-page QR sticker PDF with pdf-lib.
 *
 * The layout comes from `qr-sheet.ts`, the same module the admin preview uses,
 * so a PDF is what the screen promised. QR PNGs are generated by `qrcode`'s
 * Node entry with an *integer* module scale: fractional scaling anti-aliases
 * module edges, which is exactly what makes a printed code hard to scan.
 */
import { PDFDocument, StandardFonts, rgb, type PDFFont } from 'pdf-lib'
import QRCode from 'qrcode'
import {
  computeSheetLayout,
  sanitizeStickerText,
  stickerPdfFilename,
  STICKER_BRAND,
  STICKER_PADDING_MM,
  BRAND_BAND_MM,
  CODE_BAND_MM,
  PRODUCT_BAND_MM,
  PT_PER_MM,
  type QrSheetOptions,
  type SheetLayout,
} from './qr-sheet'

export interface StickerInput {
  code: string
  productName: string
}

export interface RenderQrSheetPdfInput {
  stickers: StickerInput[]
  options: QrSheetOptions
  /** Public site origin, no trailing slash — encoded into every QR. */
  origin: string
  brand?: string
}

export interface RenderQrSheetPdfResult {
  bytes: Uint8Array
  layout: SheetLayout
  filename: string
}

const INK = rgb(0.067, 0.094, 0.152) // #111827
const MUTED = rgb(0.29, 0.33, 0.39) // #4b5563
const BRAND_INK = rgb(0.02, 0.47, 0.34) // emerald-800
const CUT_LINE = rgb(0.82, 0.82, 0.82)

/**
 * Longest prefix of `text` that fits `maxWidth`, with an ASCII ellipsis.
 * Sanitising happens before measuring, so the standard font cannot throw.
 */
function fitText(font: PDFFont, text: string, sizePt: number, maxWidthPt: number): string {
  if (!text) return ''
  if (font.widthOfTextAtSize(text, sizePt) <= maxWidthPt) return text
  if (font.widthOfTextAtSize('...', sizePt) > maxWidthPt) return ''

  let lo = 0
  let hi = text.length
  while (lo < hi) {
    const mid = Math.ceil((lo + hi) / 2)
    const candidate = `${text.slice(0, mid).trimEnd()}...`
    if (font.widthOfTextAtSize(candidate, sizePt) <= maxWidthPt) lo = mid
    else hi = mid - 1
  }
  return `${text.slice(0, lo).trimEnd()}...`
}

function drawCentered(
  page: ReturnType<PDFDocument['addPage']>,
  text: string,
  font: PDFFont,
  sizePt: number,
  centerXpt: number,
  baselineFromTopMm: number,
  pageHeightMm: number,
  color = INK
) {
  if (!text) return
  const width = font.widthOfTextAtSize(text, sizePt)
  page.drawText(text, {
    x: centerXpt - width / 2,
    y: (pageHeightMm - baselineFromTopMm) * PT_PER_MM,
    size: sizePt,
    font,
    color,
  })
}

/** Baseline that visually centres a line of `sizePt` inside a band of `bandMm`. */
function bandBaseline(bandTopMm: number, bandMm: number, sizePt: number): number {
  return bandTopMm + bandMm / 2 + (sizePt / PT_PER_MM) * 0.35
}

export async function renderQrSheetPdf(
  input: RenderQrSheetPdfInput
): Promise<RenderQrSheetPdfResult> {
  const { stickers, options } = input
  const layout = computeSheetLayout(options, stickers.length)
  if (!layout.ok) {
    throw new Error(layout.errors.join(' '))
  }

  const origin = input.origin.replace(/\/+$/, '')
  const brand = sanitizeStickerText(input.brand ?? STICKER_BRAND)

  // Integer pixels per QR module. ~0.45 px per mm keeps the default 42 mm code
  // around 19 px/module (≈420 DPI) without fractional scaling.
  const qrScale = Math.min(20, Math.max(3, Math.round(options.qrMm * 0.45)))

  // QR generation is CPU-bound (~27 ms each). Chunking keeps the event loop
  // responsive without spawning thousands of promises at once.
  const pngs: Buffer[] = new Array(stickers.length)
  const CHUNK = 6
  for (let i = 0; i < stickers.length; i += CHUNK) {
    await Promise.all(
      stickers.slice(i, i + CHUNK).map(async (sticker, j) => {
        const url = `${origin}/donations?c=${encodeURIComponent(sticker.code)}`
        pngs[i + j] = await QRCode.toBuffer(url, {
          type: 'png',
          scale: qrScale,
          margin: 2,
          errorCorrectionLevel: 'M',
          color: { dark: '#111827', light: '#ffffff' },
        })
      })
    )
  }

  const doc = await PDFDocument.create()
  doc.setTitle('QR sticker sheet')
  doc.setSubject(`${stickers.length} pack stickers`)
  doc.setCreator('Basnayaka Vermigrow admin')
  doc.setProducer('Basnayaka Vermigrow')

  const regular = await doc.embedFont(StandardFonts.Helvetica)
  const bold = await doc.embedFont(StandardFonts.HelveticaBold)

  const { cellWidthMm, cellHeightMm, columns, perPage, pages, pageWidthMm, pageHeightMm, marginMm } =
    layout
  const maxTextWidthPt = (cellWidthMm - STICKER_PADDING_MM * 2) * PT_PER_MM

  for (let p = 0; p < pages; p++) {
    const page = doc.addPage([pageWidthMm * PT_PER_MM, pageHeightMm * PT_PER_MM])
    const pageStart = p * perPage

    for (let k = 0; k < perPage; k++) {
      const index = pageStart + k
      if (index >= stickers.length) break

      const sticker = stickers[index]
      const col = k % columns
      const row = Math.floor(k / columns)
      const cellLeftMm = layout.startXMm + col * (cellWidthMm + options.gapMm)
      const cellTopMm = layout.startYMm + row * (cellHeightMm + options.gapMm)

      page.drawRectangle({
        x: cellLeftMm * PT_PER_MM,
        y: (pageHeightMm - cellTopMm - cellHeightMm) * PT_PER_MM,
        width: cellWidthMm * PT_PER_MM,
        height: cellHeightMm * PT_PER_MM,
        borderColor: CUT_LINE,
        borderWidth: 0.4,
      })

      const contentTopMm = cellTopMm + STICKER_PADDING_MM
      const brandTopMm = contentTopMm
      const qrTopMm = brandTopMm + BRAND_BAND_MM
      const codeTopMm = qrTopMm + options.qrMm
      const productTopMm = codeTopMm + CODE_BAND_MM
      const centerXpt = (cellLeftMm + cellWidthMm / 2) * PT_PER_MM

      // Brand, two lines inside its band.
      const halfBandMm = BRAND_BAND_MM / 2
      drawCentered(
        page,
        brand.split(/\s+/)[0]?.toUpperCase() ?? '',
        bold,
        layout.fonts.brandPt,
        centerXpt,
        bandBaseline(brandTopMm, halfBandMm, layout.fonts.brandPt),
        pageHeightMm,
        BRAND_INK
      )
      const brandRest = brand.split(/\s+/).slice(1).join(' ').toUpperCase()
      drawCentered(
        page,
        fitText(bold, brandRest, layout.fonts.brandPt, maxTextWidthPt),
        bold,
        layout.fonts.brandPt,
        centerXpt,
        bandBaseline(brandTopMm + halfBandMm, halfBandMm, layout.fonts.brandPt),
        pageHeightMm,
        BRAND_INK
      )

      // QR
      const image = await doc.embedPng(pngs[index])
      page.drawImage(image, {
        x: (cellLeftMm + STICKER_PADDING_MM) * PT_PER_MM,
        y: (pageHeightMm - qrTopMm - options.qrMm) * PT_PER_MM,
        width: options.qrMm * PT_PER_MM,
        height: options.qrMm * PT_PER_MM,
      })

      // Pack code
      drawCentered(
        page,
        sticker.code,
        bold,
        layout.fonts.codePt,
        centerXpt,
        bandBaseline(codeTopMm, CODE_BAND_MM, layout.fonts.codePt),
        pageHeightMm,
        INK
      )

      // Product name
      drawCentered(
        page,
        fitText(regular, sanitizeStickerText(sticker.productName), layout.fonts.productPt, maxTextWidthPt),
        regular,
        layout.fonts.productPt,
        centerXpt,
        bandBaseline(productTopMm, PRODUCT_BAND_MM, layout.fonts.productPt),
        pageHeightMm,
        MUTED
      )
    }

    // Page number, only when the bottom margin has room for it.
    if (marginMm >= 6) {
      const sizePt = 7
      const text = `Page ${p + 1} of ${pages}`
      const width = regular.widthOfTextAtSize(text, sizePt)
      page.drawText(text, {
        x: (pageWidthMm * PT_PER_MM - width) / 2,
        y: marginMm * 0.45 * PT_PER_MM,
        size: sizePt,
        font: regular,
        color: MUTED,
      })
    }
  }

  const bytes = await doc.save()
  return {
    bytes,
    layout,
    filename: stickerPdfFilename(stickers.length, options),
  }
}
